CREATE TABLE IF NOT EXISTS inbox_reviews (bank_observation_id BIGINT UNSIGNED PRIMARY KEY,review_status VARCHAR(24) NOT NULL DEFAULT 'open',exclusion_reason VARCHAR(255) NULL,wave_transaction_id VARCHAR(255) NULL,wave_external_id VARCHAR(255) NULL,last_export_error TEXT NULL,reviewed_by BIGINT UNSIGNED NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS inbox_allocations (allocation_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,bank_observation_id BIGINT UNSIGNED NOT NULL,line_number INT UNSIGNED NOT NULL,export_account VARCHAR(255) NOT NULL,amount DECIMAL(12,2) NOT NULL,allocation_note VARCHAR(255) NULL,created_by BIGINT UNSIGNED NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_inbox_allocation_line(bank_observation_id,line_number),KEY idx_inbox_allocation_observation(bank_observation_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;